def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Full grid-spanning lines partition the picture into cells.
    row_bars = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    col_bars = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != 0]

    def segments(length, bars):
        result, start = [], 0
        for b in bars:
            if start < b:
                result.append((start, b))
            start = b + 1
        if start < length:
            result.append((start, length))
        return result

    row_cells = segments(h, row_bars)
    col_cells = segments(w, col_bars)

    # Record each color's occupied local coordinates in every cell.
    cells = {}
    for ri, (r0, r1) in enumerate(row_cells):
        for ci, (c0, c1) in enumerate(col_cells):
            shapes = {}
            for r in range(r0, r1):
                for c in range(c0, c1):
                    color = grid[r][c]
                    if color != 0:
                        shapes.setdefault(color, set()).add((r - r0, c - c0))
            cells[ri, ci] = shapes

    # Find the mirror axis associated with each object color from a pair
    # of neighboring cells that already contain matching reflected shapes.
    axes = {}
    for ri, (r0, r1) in enumerate(row_cells):
        for ci in range(len(col_cells) - 1):
            c0, c1 = col_cells[ci]
            d0, d1 = col_cells[ci + 1]
            width = c1 - c0
            if d1 - d0 != width:
                continue
            left, right = cells[ri, ci], cells[ri, ci + 1]
            for color in left.keys() & right.keys():
                a, b = left[color], right[color]
                reflected = {(y, width - 1 - x) for y, x in a}
                if reflected == b:
                    axes.setdefault(color, (ci, ci + 1))

    # Complete each color's mirrored pair in every row band.
    for color, (left_ci, right_ci) in axes.items():
        for ri, (r0, r1) in enumerate(row_cells):
            for source_ci, target_ci in ((left_ci, right_ci), (right_ci, left_ci)):
                source = cells[ri, source_ci].get(color)
                target = cells[ri, target_ci].get(color)
                if not source or target:
                    continue
                tc0, tc1 = col_cells[target_ci]
                width = tc1 - tc0
                for y, x in source:
                    out[r0 + y][tc0 + width - 1 - x] = color

    return out
